export const documentCSS="body.document-mode {\n  overflow: hidden;\n  background: #f6f6f6;\n}\n.document-mode > .topbar,\n.document-mode > .layout,\n.document-mode > .mobile-bottom-nav,\n.document-mode > .sidebar-scrim,\n.document-mode > #toast {\n  display: none !important;\n}\n#document-editor-root {\n  height: 100dvh;\n}\n.document-editor {\n  height: 100%;\n  display: flex;\n  flex-direction: column;\n  color: #242424;\n  font:\n    13px \"DM Sans\",\n    \"Noto Sans KR\",\n    system-ui,\n    sans-serif;\n  background: #f5f5f5;\n}\n.document-header {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  padding: 16px 24px;\n  background: #fff;\n  border-bottom: 1px solid #e9e9e9;\n}\n.document-logo {\n  display: grid;\n  place-items: center;\n  width: 40px;\n  height: 40px;\n  background: #f2f2f2;\n  border-radius: 10px;\n}\n.document-logo svg {\n  width: 22px;\n  height: 22px;\n}\n.document-heading {\n  min-width: 0;\n  flex: 1;\n}\n.document-heading h1 {\n  font-size: 17px;\n  line-height: 1.4;\n  letter-spacing: -0.4px;\n  margin: 0 0 3px;\n  font-weight: 600;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n.document-heading [role=\"status\"] {\n  font-size: 11px;\n  color: #777;\n}\n.document-autosave-label {\n  font-size: 11px;\n  color: #777;\n  background: #f4f4f4;\n  padding: 6px 10px;\n  border-radius: 8px;\n}\n.document-toolbar {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  flex-wrap: wrap;\n  padding: 8px 20px;\n  background: #fff;\n  border-bottom: 1px solid #e9e9e9;\n}\n.document-toolbar button.keep-label,\n.document-toolbar select.keep-label,\n.document-error button.keep-label {\n  height: 32px !important;\n  min-height: 32px !important;\n  width: auto !important;\n  min-width: 32px !important;\n  max-width: none !important;\n  padding: 0 9px !important;\n  font-family: inherit !important;\n  font-size: 12px !important;\n  border: 0 !important;\n  border-radius: 7px !important;\n  background: transparent;\n  color: #242424;\n  box-shadow: none !important;\n}\n.document-toolbar .document-tool:hover,\n.document-toolbar .selected {\n  background: #e9e9e9 !important;\n}\n.document-toolbar button:disabled {\n  opacity: 0.4;\n}\n.document-tool-divider {\n  width: 1px;\n  height: 18px;\n  background: #ddd;\n  margin: 0 5px;\n}\n.document-color {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  font-size: 11px;\n  white-space: nowrap;\n}\n.document-color input {\n  width: 24px !important;\n  min-width: 24px !important;\n  height: 26px !important;\n  min-height: 26px !important;\n  border: 0 !important;\n  border-radius: 0 !important;\n  box-shadow: none !important;\n  background: transparent;\n  padding: 0 !important;\n}\n.document-scroll {\n  flex: 1;\n  overflow: auto;\n  padding: 28px 16px;\n  min-height: 0;\n  overscroll-behavior: contain;\n}\n.document-sheet {\n  max-width: 794px;\n  min-height: 1123px;\n  margin: 0 auto;\n  padding: 72px 76px;\n  background: #fff;\n  border: 1px solid #e8e8e8;\n  border-radius: 3px;\n  box-shadow: 0 2px 10px #00000006;\n  box-sizing: border-box;\n}\n.document-sheet .tiptap {\n  outline: none;\n  min-height: 970px;\n  line-height: 1.75;\n  font-size: 11pt;\n  color: #242424;\n  overflow-wrap: anywhere;\n  white-space: pre-wrap;\n}\n.document-sheet [contenteditable=\"true\"],\n.document-sheet [contenteditable=\"true\"]:hover,\n.document-sheet [contenteditable=\"true\"]:focus {\n  background: transparent !important;\n  box-shadow: none !important;\n  cursor: text;\n}\n.document-sheet p {\n  margin: 0 0 12px;\n}\n.document-sheet h1,\n.document-sheet h2,\n.document-sheet h3 {\n  margin: 20px 0 12px;\n  line-height: 1.4;\n}\n.document-sheet ul,\n.document-sheet ol {\n  padding-left: 28px;\n}\n.document-sheet a {\n  color: inherit;\n  text-decoration: underline;\n}\n.document-sheet img {\n  max-width: 100%;\n  height: auto;\n}\n.document-sheet table {\n  table-layout: fixed;\n  border-collapse: collapse;\n  width: 100%;\n  margin: 12px 0;\n}\n.document-sheet th,\n.document-sheet td {\n  border: 1px solid #ccc;\n  padding: 8px;\n  min-width: 30px;\n  position: relative;\n  background: white;\n  color: #242424;\n  font-weight: 400;\n}\n.document-sheet td p,\n.document-sheet th p {\n  margin: 0;\n}\n.document-sheet .selectedCell:after {\n  content: \"\";\n  position: absolute;\n  inset: 0;\n  background: #0000000a;\n  pointer-events: none;\n}\n.document-preserved {\n  background: #f7f7f7;\n  border: 1px dashed #ddd;\n  border-radius: 8px;\n  padding: 12px;\n  margin: 12px 0;\n  font-size: 11px;\n  color: #777;\n}\n.document-error {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: 8px;\n  padding: 10px 24px;\n  background: #fff4f3;\n  color: #a6362c;\n  border-bottom: 1px solid #eedbd8;\n  font-size: 12px;\n}\n.document-error span {\n  flex: 1;\n  min-width: 200px;\n}\n.document-error button {\n  background: white !important;\n}\n.document-footer {\n  padding: 9px 24px;\n  color: #888;\n  font-size: 11px;\n  background: #fff;\n  border-top: 1px solid #e9e9e9;\n}\n.document-open-actions {\n  display: flex;\n  justify-content: flex-end;\n  padding: 8px 0;\n}\n.document-open-actions button {\n  font-size: 12px;\n}\n.file-document-open {\n  font-size: 12px;\n  text-align: left;\n  background: transparent;\n  border: 0;\n  padding: 4px 0;\n  color: #242424;\n}\n@media (max-width: 720px) {\n  .document-header {\n    padding: 12px 14px;\n    gap: 10px;\n  }\n  .document-heading h1 {\n    font-size: 15px;\n  }\n  .document-toolbar {\n    padding: 8px 10px;\n    gap: 2px;\n  }\n  .document-scroll {\n    padding: 12px 8px;\n  }\n  .document-sheet {\n    padding: 28px 22px;\n    min-height: calc(100dvh - 200px);\n  }\n  .document-sheet .tiptap {\n    min-height: calc(100dvh - 260px);\n  }\n  .document-autosave-label {\n    display: none;\n  }\n  .document-footer {\n    padding: 8px 14px;\n  }\n  .document-error {\n    padding: 10px 14px;\n  }\n}\n\n.document-layout-controls {\n  display: flex;\n  gap: 10px;\n  flex-wrap: wrap;\n  margin: 0;\n  padding: 8px 14px;\n  border: 0;\n  border-bottom: 1px solid #eee;\n  flex: none;\n}\n.document-layout-controls label {\n  font-size: 11px;\n  display: grid;\n  gap: 4px;\n}\n.document-layout-controls input {\n  width: 86px;\n  padding: 6px;\n  border: 0;\n  border-radius: 7px;\n  background: #f3f3f3;\n}\n.document-comment-form {\n  display: flex;\n  gap: 8px;\n  align-items: end;\n  padding: 10px 14px;\n  flex-wrap: wrap;\n}\n.document-comment-form label {\n  flex: 1;\n  display: grid;\n  gap: 4px;\n}\n.document-comment-form input {\n  width: 100%;\n  padding: 8px;\n  background: #f5f5f5;\n  border: 0;\n  border-radius: 8px;\n}\n.document-comments {\n  flex: none;\n  max-height: 160px;\n  overflow: auto;\n  padding: 8px 14px;\n  border-bottom: 1px solid #eee;\n  overscroll-behavior: contain;\n}\n.document-comments > div {\n  display: flex;\n  gap: 8px;\n  justify-content: space-between;\n}\n.document-comments button {\n  border: 0;\n  background: transparent;\n  text-align: left;\n}\n.docx-comment {\n  background: #fff0b3;\n  border-bottom: 2px solid #e4b000;\n}\n.document-toolbar {\n  max-height: 160px;\n  overflow: auto;\n  overscroll-behavior: contain;\n}\n.document-editor {\n  min-width: 0;\n}\n.document-sheet img {\n  max-width: 100%;\n  height: auto;\n}\n@media (max-width: 720px) {\n  .document-sheet {\n    min-height: 70dvh;\n    padding-top: 24px !important;\n    padding-bottom: 24px !important;\n  }\n  .document-toolbar {\n    max-height: 180px;\n  }\n  .document-header {\n    flex-wrap: wrap;\n  }\n  .document-header button {\n    border: 0;\n    padding: 8px;\n    font-size: 12px;\n  }\n  .document-layout-controls {\n    max-height: 140px;\n    overflow: auto;\n  }\n  .document-comment-form {\n    padding: 8px;\n  }\n  .document-scroll {\n    padding: 10px 6px;\n  }\n}\n\nhtml.document-html {\n  overflow: hidden;\n  height: 100%;\n}\nbody.document-mode,\n#document-editor-root {\n  height: var(--document-height, 100dvh);\n}\n.document-header button {\n  border: 0;\n  border-radius: 8px;\n  padding: 8px 10px;\n  background: #f5f5f5;\n  color: inherit;\n}\n.document-header .ui-icon {\n  width: 20px;\n  height: 20px;\n}\n.document-toolbar .document-tool {\n  min-height: 36px !important;\n}\n.document-toolbar select {\n  min-height: 36px !important;\n}\n";
